import gzip
import json
import sys
from collections import Counter, defaultdict


def parse_attrs(attr_text):
    attrs = {}
    for field in attr_text.rstrip(";").split(";"):
        field = field.strip()
        if not field:
            continue
        if " " not in field:
            attrs[field] = ""
            continue
        key, value = field.split(" ", 1)
        attrs[key] = value.strip().strip('"')
    return attrs


def is_standard(seqid):
    if seqid == "NC_012920.1":
        return True
    if seqid.startswith("NC_"):
        try:
            n = int(seqid.split("_", 1)[1].split(".", 1)[0])
        except ValueError:
            return False
        return 1 <= n <= 24
    if seqid.startswith("chr"):
        chrom = seqid[3:]
        return chrom in {str(i) for i in range(1, 23)} | {"X", "Y", "M", "MT"}
    return seqid in {str(i) for i in range(1, 23)} | {"X", "Y", "MT", "M"}


gtf_path, out_path = sys.argv[1:3]
feature_counts = Counter()
seq_counts = Counter()
mane_attr_counts = Counter()
mane_feature_counts = Counter()
mane_standard_feature_counts = Counter()
transcript_tags = defaultdict(set)
examples = {}
total_lines = 0

with gzip.open(gtf_path, "rt") as handle:
    for line in handle:
        if not line or line.startswith("#"):
            continue
        total_lines += 1
        parts = line.rstrip("\n").split("\t")
        if len(parts) != 9:
            continue
        seqid, _source, feature, start, end, _score, strand, _phase, attr_text = parts
        attrs = parse_attrs(attr_text)
        feature_counts[feature] += 1
        seq_counts[seqid] += 1
        tag_values = []
        if "tag" in attrs:
            tag_values.extend([v.strip() for v in attrs["tag"].split(",")])
        for key, value in attrs.items():
            if "mane" in key.lower() or "mane" in value.lower():
                mane_attr_counts[f"{key}={value}"] += 1
        is_mane = any(v == "MANE Select" for v in tag_values)
        if is_mane:
            tx_id = attrs.get("transcript_id", "")
            transcript_tags[tx_id].update(tag_values)
            mane_feature_counts[feature] += 1
            if is_standard(seqid):
                mane_standard_feature_counts[feature] += 1
                examples.setdefault(feature, {
                    "seqid": seqid,
                    "feature": feature,
                    "start": int(start),
                    "end": int(end),
                    "strand": strand,
                    "transcript_id": tx_id,
                    "gene_id": attrs.get("gene_id", ""),
                    "tag": attrs.get("tag", ""),
                })

summary = {
    "total_feature_lines": total_lines,
    "feature_counts": feature_counts.most_common(),
    "top_seqids": seq_counts.most_common(30),
    "mane_attribute_examples": mane_attr_counts.most_common(20),
    "mane_transcripts": len([tx for tx in transcript_tags if tx]),
    "mane_feature_counts": mane_feature_counts.most_common(),
    "mane_standard_feature_counts": mane_standard_feature_counts.most_common(),
    "mane_standard_examples": examples,
}

with open(out_path, "w") as out:
    json.dump(summary, out, indent=2, sort_keys=True)
    out.write("\n")

