import gzip
import json
import sys
from collections import Counter, defaultdict

import numpy as np


STANDARD = {f"chr{i}" for i in range(1, 23)} | {"chrX", "chrY", "chrM", "chrMT"}


def parse_attrs(attr_text):
    attrs = {}
    for field in attr_text.rstrip(";").split(";"):
        field = field.strip()
        if not field:
            continue
        if " " not in field:
            attrs[field] = ""
            continue
        key, value = field.split(" ", 1)
        attrs[key] = value.strip().strip('"')
    return attrs


def is_mane_select(attrs):
    return any(tag.strip() == "MANE Select" for tag in attrs.get("tag", "").split(","))


def merge_intervals(intervals):
    if not intervals:
        return []
    merged = []
    for start, end in sorted(intervals):
        if not merged or start > merged[-1][1] + 1:
            merged.append([start, end])
        elif end > merged[-1][1]:
            merged[-1][1] = end
    return [(start, end) for start, end in merged]


def interval_len(intervals):
    return sum(end - start + 1 for start, end in intervals)


def left_len(intervals, boundary):
    total = 0
    for start, end in intervals:
        if start < boundary:
            total += max(0, min(end, boundary - 1) - start + 1)
    return total


def right_len(intervals, boundary):
    total = 0
    for start, end in intervals:
        if end > boundary:
            total += max(0, end - max(start, boundary + 1) + 1)
    return total


gtf_path, result_path, detail_path = sys.argv[1:4]

transcripts = {}
feature_counts = Counter()

with gzip.open(gtf_path, "rt") as handle:
    for line in handle:
        if not line or line.startswith("#"):
            continue
        parts = line.rstrip("\n").split("\t")
        if len(parts) != 9:
            continue
        seqid, _source, feature, start, end, _score, strand, _phase, attr_text = parts
        attrs = parse_attrs(attr_text)
        if feature == "transcript" and seqid in STANDARD and is_mane_select(attrs):
            tx_id = attrs.get("transcript_id")
            if tx_id:
                transcripts[tx_id] = {
                    "seqid": seqid,
                    "strand": strand,
                    "exons": [],
                    "coding": [],
                }

with gzip.open(gtf_path, "rt") as handle:
    for line in handle:
        if not line or line.startswith("#"):
            continue
        parts = line.rstrip("\n").split("\t")
        if len(parts) != 9:
            continue
        seqid, _source, feature, start, end, _score, strand, _phase, attr_text = parts
        attrs = parse_attrs(attr_text)
        tx_id = attrs.get("transcript_id")
        if tx_id not in transcripts or seqid != transcripts[tx_id]["seqid"]:
            continue
        start_i, end_i = int(start), int(end)
        if feature == "exon":
            transcripts[tx_id]["exons"].append((start_i, end_i))
            feature_counts["exon"] += 1
        elif feature in {"CDS", "stop_codon"}:
            transcripts[tx_id]["coding"].append((start_i, end_i))
            feature_counts[feature] += 1

lengths = {"five_prime_utr": [], "cds": [], "three_prime_utr": []}
skipped = Counter()
per_transcript = []

for tx_id, tx in transcripts.items():
    exons = merge_intervals(tx["exons"])
    coding = merge_intervals(tx["coding"])
    if not exons:
        skipped["no_exon"] += 1
        continue
    if not coding:
        skipped["no_coding"] += 1
        continue

    coding_start = min(start for start, _end in coding)
    coding_end = max(end for _start, end in coding)
    cds_len = interval_len(coding)

    if tx["strand"] == "-":
        five_prime = right_len(exons, coding_end)
        three_prime = left_len(exons, coding_start)
    else:
        five_prime = left_len(exons, coding_start)
        three_prime = right_len(exons, coding_end)

    lengths["five_prime_utr"].append(five_prime)
    lengths["cds"].append(cds_len)
    lengths["three_prime_utr"].append(three_prime)
    per_transcript.append((tx_id, five_prime, cds_len, three_prime))

medians = {
    key: int(np.floor(np.median(values)))
    for key, values in lengths.items()
}
answer = f"{medians['five_prime_utr']};{medians['cds']};{medians['three_prime_utr']}"

detail = {
    "answer": answer,
    "numpy_version": np.__version__,
    "standard_chromosomes": sorted(STANDARD),
    "mane_select_standard_transcripts": len(transcripts),
    "transcripts_used_for_medians": len(lengths["cds"]),
    "skipped": dict(skipped),
    "aggregated_feature_counts": dict(feature_counts),
    "raw_medians": {
        key: float(np.median(values))
        for key, values in lengths.items()
    },
    "floored_medians": medians,
    "length_min_max": {
        key: [int(min(values)), int(max(values))]
        for key, values in lengths.items()
    },
    "first_five_transcripts": per_transcript[:5],
}

with open(result_path, "w") as out:
    out.write(answer + "\n")

with open(detail_path, "w") as out:
    json.dump(detail, out, indent=2, sort_keys=True)
    out.write("\n")

